func (s *manualAdminPortalService) GetAnalyticsDashboard(ctx context.Context, _ *emptypb.Empty) (*adminv1.AnalyticsDashboardResponse, error) {
	now := time.Now()
	overview := &adminv1.AnalyticsOverview{}
	trend := &adminv1.AnalyticsTrend{}
	visits := &adminv1.AnalyticsVisit{}

	if s.userCountReader != nil {
		userSummary, err := s.userCountReader.CountSummary(ctx, now)
		if err != nil {
			return nil, err
		}
		if userSummary != nil {
			overview.TotalUsers = userSummary.Total
			overview.CurrentUsers = userSummary.Created24
		}
	}

	sourceDistributions := make([]*adminv1.AnalyticsNamedValue, 0)
	businessDistributions := make([]*adminv1.AnalyticsNamedValue, 0)
	platformDistributions := make([]*adminv1.AnalyticsNamedValue, 0)
	if s.apiAnalyticsReader != nil {
		summary, err := s.apiAnalyticsReader.AnalyticsSummary(ctx, now)
		if err != nil {
			return nil, err
		}
		if summary != nil {
			overview.TotalAccesses = summary.TotalAccesses
			overview.CurrentAccesses = summary.CurrentAccesses
			overview.TotalDownloads = summary.TotalDownloads
			overview.CurrentDownloads = summary.CurrentDownloads
			overview.TotalUsages = summary.TotalUsages
			overview.CurrentUsages = summary.CurrentActives

			trend.Labels = make([]string, 0, len(summary.Trends))
			trend.Accesses = make([]uint64, 0, len(summary.Trends))
			trend.Actives = make([]uint64, 0, len(summary.Trends))
			for _, item := range summary.Trends {
				trend.Labels = append(trend.Labels, item.Label)
				trend.Accesses = append(trend.Accesses, item.Accesses)
				trend.Actives = append(trend.Actives, item.Actives)
			}

			visits.Labels = make([]string, 0, len(summary.Visits))
			visits.Accesses = make([]uint64, 0, len(summary.Visits))
			for _, item := range summary.Visits {
				visits.Labels = append(visits.Labels, item.Label)
				visits.Accesses = append(visits.Accesses, item.Value)
			}

			sourceDistributions = toAnalyticsNamedValues(summary.Sources)
			businessDistributions = toAnalyticsNamedValues(summary.Businesses)
			platformDistributions = toAnalyticsNamedValues(summary.Platforms)
		}
	}

	return &adminv1.AnalyticsDashboardResponse{
		Overview:              overview,
		Trend:                 trend,
		Visits:                visits,
		SourceDistributions:   sourceDistributions,
		BusinessDistributions: businessDistributions,
		PlatformDistributions: platformDistributions,
	}, nil
}

