func (s *manualAdminPortalService) loadUserPermissionCodes(ctx context.Context) ([]string, error) {
	if viewer, ok := crudviewer.FromContext(ctx); ok {
		codes := viewer.Permissions()
		if len(codes) > 0 {
			return uniqueSortedStrings(codes), nil
		}
	}
	if s.roleRepo == nil || s.permRepo == nil {
		return nil, nil
	}

	roleIDs, err := s.loadUserRoleIDs(ctx)
	if err != nil || len(roleIDs) == 0 {
		return nil, err
	}

	permissionIDs, err := s.roleRepo.ListPermissionIDsByRoleIDs(ctx, roleIDs)
	if err != nil || len(permissionIDs) == 0 {
		return nil, err
	}

	codes, err := s.permRepo.GetPermissionCodesByIDs(ctx, permissionIDs)
	if err != nil {
		return nil, err
	}
	return uniqueSortedStrings(codes), nil
}

func (s *manualAdminPortalService) loadUserNavigation(ctx context.Context) ([]*resourcev1.MenuRouteItem, error) {
	if s.menuStore == nil || s.roleRepo == nil {
		return nil, nil
	}

	roleIDs, err := s.loadUserRoleIDs(ctx)
	if err != nil || len(roleIDs) == 0 {
		return nil, err
	}

	menuIDs, err := s.roleRepo.GetRolesPermissionMenuIDs(ctx, roleIDs)
	if err != nil || len(menuIDs) == 0 {
		return nil, err
	}
	return s.menuStore.ListNavigationRoutesByIDs(ctx, menuIDs)
}

func (s *manualAdminPortalService) loadUserRoleIDs(ctx context.Context) ([]uint32, error) {
	viewer, ok := crudviewer.FromContext(ctx)
	if !ok || viewer.UserID() == 0 {
		return nil, nil
	}

	userID := uint32(viewer.UserID())
	if s.userRoleReader != nil {
		return s.userRoleReader.ListRoleIDsByUserID(ctx, userID)
	}
	if s.userRepo == nil {
		return nil, nil
	}
	user, err := s.userRepo.Get(ctx, &identityv1.GetUserRequest{
		QueryBy: &identityv1.GetUserRequest_Id{Id: userID},
	})
	if err != nil || user == nil {
		return nil, err
	}
	return user.GetRoleIds(), nil
}

func uniqueSortedStrings(values []string) []string {
	if len(values) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(values))
	result := make([]string, 0, len(values))
	for _, value := range values {
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		result = append(result, value)
	}
	sort.Strings(result)
	return result
}

func toAnalyticsNamedValues(items []repo.ApiAuditNamedValue) []*adminv1.AnalyticsNamedValue {
	if len(items) == 0 {
		return nil
	}
	result := make([]*adminv1.AnalyticsNamedValue, 0, len(items))
	for _, item := range items {
		name := strings.TrimSpace(item.Name)
		if name == "" {
			continue
		}
		result = append(result, &adminv1.AnalyticsNamedValue{
			Name:  name,
			Value: item.Value,
		})
	}
	return result
}

func ptr[T any](value T) *T {
	return &value
}
